INSERT INTO public.conversation_message (id, conversation_id, utilisateur_id, admin_id, corps, cree_le) VALUES (1, 2, '6c9bc571-b64a-427c-860c-e34cd932c561', NULL, 'Bonjour, pourriez-vous préciser la répartition du versement de septembre entre les quatre projets soutenus ? Notre conseil d’administration le demande.', '2026-09-15 10:00:00+03');
INSERT INTO public.conversation_message (id, conversation_id, utilisateur_id, admin_id, corps, cree_le) VALUES (2, 2, NULL, 1, 'Bonjour, la répartition figure désormais dans votre rapport trimestriel, section « Emploi des fonds ». En résumé : 43,9 % scolarité, 29,3 % soins, 26,8 % alimentation.', '2026-09-15 14:00:00+03');
INSERT INTO public.conversation_message (id, conversation_id, utilisateur_id, admin_id, corps, cree_le) VALUES (3, 3, '6c9bc571-b64a-427c-860c-e34cd932c561', NULL, 'Nous souhaiterions visiter deux sites début décembre avec une délégation de trois personnes. Est-ce envisageable ?', '2026-09-12 08:00:00+03');
INSERT INTO public.conversation_message (id, conversation_id, utilisateur_id, admin_id, corps, cree_le) VALUES (4, 4, '8690906a-68ba-4a25-b067-bb0668aae3a5', NULL, 'Bonjour, pourriez-vous préciser la répartition du versement de septembre entre les quatre projets soutenus ? Notre conseil d’administration le demande.', '2026-09-15 10:00:00+03');
INSERT INTO public.conversation_message (id, conversation_id, utilisateur_id, admin_id, corps, cree_le) VALUES (5, 4, NULL, 1, 'Bonjour, la répartition figure désormais dans votre rapport trimestriel, section « Emploi des fonds ». En résumé : 43,9 % scolarité, 29,3 % soins, 26,8 % alimentation.', '2026-09-15 14:00:00+03');
INSERT INTO public.conversation_message (id, conversation_id, utilisateur_id, admin_id, corps, cree_le) VALUES (6, 5, '8690906a-68ba-4a25-b067-bb0668aae3a5', NULL, 'Nous souhaiterions visiter deux sites début décembre avec une délégation de trois personnes. Est-ce envisageable ?', '2026-09-12 08:00:00+03');
INSERT INTO public.conversation_message (id, conversation_id, utilisateur_id, admin_id, corps, cree_le) VALUES (7, 6, 'e928bd96-148f-416d-9325-2d1f695e75f0', NULL, 'Bonjour, je peux prendre les samedis matin à partir du 8 novembre. Y a-t-il des missions de soutien scolaire ce jour-là ? Merci.', '2026-09-16 04:00:00+03');
INSERT INTO public.conversation_message (id, conversation_id, utilisateur_id, admin_id, corps, cree_le) VALUES (8, 6, NULL, 1, 'Bonjour, merci pour votre disponibilité. Nous ouvrons deux créneaux le samedi matin à Ankadifotsy à partir du 8 ; ils apparaîtront dans vos missions la semaine prochaine.', '2026-09-16 07:00:00+03');
INSERT INTO public.conversation_message (id, conversation_id, utilisateur_id, admin_id, corps, cree_le) VALUES (9, 7, 'e928bd96-148f-416d-9325-2d1f695e75f0', NULL, 'Mon employeur me demande une attestation des heures effectuées cette année. Pouvez-vous me l’établir ?', '2026-09-02 08:00:00+03');
INSERT INTO public.conversation_message (id, conversation_id, utilisateur_id, admin_id, corps, cree_le) VALUES (10, 7, NULL, 1, 'C’est fait, l’attestation part par courriel aujourd’hui. Elle reprend les heures validées de votre journal, arrêtées à hier.', '2026-09-02 12:00:00+03');
INSERT INTO public.conversation_message (id, conversation_id, utilisateur_id, admin_id, corps, cree_le) VALUES (11, 8, 'e928bd96-148f-416d-9325-2d1f695e75f0', NULL, 'Faut-il apporter sa propre machine pour l’atelier du mois prochain, ou HOPE en fournit ?', '2026-09-16 10:00:00+03');
