INSERT INTO public.message_entree (id, fil_id, auteur, corps, admin_id, lu, cree_le) VALUES (7, 5, 'utilisateur', 'Bonjour, je peux prendre les samedis matin à partir du 8 novembre. Y a-t-il des missions de soutien scolaire ce jour-là ? Merci.', NULL, true, '2026-09-16 04:00:00+03');
INSERT INTO public.message_entree (id, fil_id, auteur, corps, admin_id, lu, cree_le) VALUES (8, 5, 'hope', 'Bonjour, merci pour votre disponibilité. Nous ouvrons deux créneaux le samedi matin à Ankadifotsy à partir du 8 ; ils apparaîtront dans vos missions la semaine prochaine.', 1, false, '2026-09-16 07:00:00+03');
INSERT INTO public.message_entree (id, fil_id, auteur, corps, admin_id, lu, cree_le) VALUES (9, 6, 'utilisateur', 'Mon employeur me demande une attestation des heures effectuées cette année. Pouvez-vous me l’établir ?', NULL, true, '2026-09-02 08:00:00+03');
INSERT INTO public.message_entree (id, fil_id, auteur, corps, admin_id, lu, cree_le) VALUES (10, 6, 'hope', 'C’est fait, l’attestation part par courriel aujourd’hui. Elle reprend les heures validées de votre journal, arrêtées à hier.', 1, true, '2026-09-02 12:00:00+03');
INSERT INTO public.message_entree (id, fil_id, auteur, corps, admin_id, lu, cree_le) VALUES (11, 7, 'utilisateur', 'Faut-il apporter sa propre machine pour l’atelier du mois prochain, ou HOPE en fournit ?', NULL, false, '2026-09-16 10:00:00+03');
