-- ------------------------------------------------------------
-- Sequences
--
-- Les identifiants ci-dessus sont ecrits en clair. Sans ces
-- appels, la prochaine insertion faite par l'application
-- repartirait de un et heurterait une cle primaire deja prise.
--
-- PERFORM plutot que SELECT : setval renvoie une ligne, et
-- vingt-cinq tableaux de resultat noieraient la seule sortie qui
-- compte -- celle qui signale une erreur.
-- ------------------------------------------------------------
DO $$
BEGIN
  PERFORM pg_catalog.setval('public.activity_log_id_seq', 8, true);
  PERFORM pg_catalog.setval('public.beneficiaries_id_seq', 12, true);
  PERFORM pg_catalog.setval('public.conversation_id_seq', 23, true);
  PERFORM pg_catalog.setval('public.conversation_message_id_seq', 36, true);
  PERFORM pg_catalog.setval('public.conversation_participant_id_seq', 44, true);
  PERFORM pg_catalog.setval('public.donations_id_seq', 19, true);
  PERFORM pg_catalog.setval('public.donor_accounts_id_seq', 4, true);
  PERFORM pg_catalog.setval('public.donors_id_seq', 15, true);
  PERFORM pg_catalog.setval('public.expenses_id_seq', 6, true);
  PERFORM pg_catalog.setval('public.field_proof_files_id_seq', 1, false);
  PERFORM pg_catalog.setval('public.field_proofs_id_seq', 1, false);
  PERFORM pg_catalog.setval('public.impacts_id_seq', 4, true);
  PERFORM pg_catalog.setval('public.investments_id_seq', 3, true);
  PERFORM pg_catalog.setval('public.message_entree_id_seq', 36, true);
  PERFORM pg_catalog.setval('public.message_utilisateur_id_seq', 22, true);
  PERFORM pg_catalog.setval('public.messages_id_seq', 4, true);
  PERFORM pg_catalog.setval('public.notification_utilisateur_id_seq', 38, true);
  PERFORM pg_catalog.setval('public.notifications_id_seq', 26, true);
  PERFORM pg_catalog.setval('public.project_beneficiaries_id_seq', 12, true);
  PERFORM pg_catalog.setval('public.project_categories_id_seq', 14, true);
  PERFORM pg_catalog.setval('public.project_objectives_id_seq', 1, false);
  PERFORM pg_catalog.setval('public.project_quote_items_id_seq', 1, false);
  PERFORM pg_catalog.setval('public.projects_id_seq', 5, true);
  PERFORM pg_catalog.setval('public.supporting_documents_id_seq', 4, true);
END;
$$;

COMMIT;
